// ============================================================
// VALIDATOR AGENT (v2 — Tuned)
// Cross-checks classifier verdict against grounding signals
// ============================================================

const input = $input.first().json;

const verdict = input.verdict || 'unknown';
const confidence = input.confidence || 0;
const binaryVerdict = input.binary_verdict || 'unknown';
const context = input.context || '';
const senderDomain = input.sender_domain || 'unknown';
const emailText = input.email_text || '';

// ─── Detect grounding signals from context ───
const domainKnown = context.includes('is known');
const hasInteractions = context.includes('has emailed this recipient');
const isFirstContact = context.includes('first-time contact');

// ─── Initialize output ───
let validatedVerdict = verdict;
let trustScore = confidence;
let needsReview = false;
let validationNotes = [];

// ─── Rule 1: Low confidence → flag for review ───
if (confidence < 0.70) {
  needsReview = true;
  trustScore = confidence * 0.8;
  validationNotes.push(`Low confidence (${confidence}) — flagged for review`);
}

// ─── Rule 2: Binary/judge mismatch → flag ───
const binarySaysMalicious = binaryVerdict === 'malicious';
const finalSaysMalicious = ['phishing', 'bec'].includes(verdict);

if (binarySaysMalicious !== finalSaysMalicious) {
  needsReview = true;
  trustScore = trustScore * 0.7;
  validationNotes.push(`Binary/judge mismatch: binary=${binaryVerdict}, judge=${verdict}`);
}

// ─── Rule 3 (TUNED): Malicious + known domain + history + LOW confidence → downgrade ───
if (finalSaysMalicious && domainKnown && hasInteractions && confidence < 0.90) {
  validatedVerdict = 'suspicious';
  trustScore = trustScore * 0.85;
  needsReview = true;
  validationNotes.push(`Malicious verdict from known domain "${senderDomain}" with confidence ${confidence} — downgraded to suspicious`);
}
else if (finalSaysMalicious && domainKnown && hasInteractions && confidence >= 0.90) {
  // High-confidence malicious from known domain — still flag but keep verdict
  needsReview = true;
  validationNotes.push(`High-confidence malicious from known domain "${senderDomain}" — flagged for human review`);
}

// ─── Rule 4 (TUNED): Legitimate + unknown + first contact + LOW confidence → upgrade ───
if (verdict === 'legitimate' && !domainKnown && isFirstContact && confidence < 0.85) {
  validatedVerdict = 'suspicious';
  trustScore = trustScore * 0.85;
  needsReview = true;
  validationNotes.push(`Legitimate verdict from unknown domain with confidence ${confidence} — upgraded to suspicious`);
}

// ─── Rule 5: High-confidence malicious from unknown domain → confirm ───
if (finalSaysMalicious && !domainKnown && confidence > 0.85 && !needsReview) {
  validationNotes.push(`High-confidence malicious from unknown domain — confirmed`);
}

// ─── Rule 6: High-confidence legitimate from known domain → confirm ───
if (verdict === 'legitimate' && domainKnown && hasInteractions && confidence > 0.85) {
  validationNotes.push(`High-confidence legitimate from known domain with history — confirmed`);
}

// ─── Default note if none triggered ───
if (validationNotes.length === 0) {
  validationNotes.push(`Verdict "${verdict}" accepted with confidence ${confidence}`);
}

// ─── Round trust score ───
trustScore = Math.round(trustScore * 100) / 100;

// ─── Return final output ───
return [{
  json: {
    final_verdict: validatedVerdict,
    original_verdict: verdict,
    confidence: confidence,
    trust_score: trustScore,
    needs_review: needsReview,
    validation_notes: validationNotes,
    binary_verdict: binaryVerdict,
    sender_domain: senderDomain,
    email_text: emailText,
    context: context,
    validated_at: new Date().toISOString()
  }
}];
